pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime1, uint256 _unlockTime2) public {
        // Keep unlock times in a reasonable future range
        _unlockTime1 = bound(_unlockTime1, block.timestamp, block.timestamp + 365 days);
        _unlockTime2 = bound(_unlockTime2, block.timestamp, block.timestamp + 365 days);
        // Ensure second unlock time is larger than the first to make the difference observable
        vm.assume(_unlockTime2 > _unlockTime1);

        // Make two consecutive Put calls from the same caller
        address actor = address(0x123);
        vm.deal(actor, 2 ether);
        vm.startPrank(actor);
        c.Put{value: 1 ether}(_unlockTime1);
        c.Put{value: 1 ether}(_unlockTime2);
        vm.stopPrank();

        // After two Puts, the stored unlockTime must equal the larger of _unlockTime2 and block.timestamp
        (uint storedUnlock, ) = c.Acc(actor);
        uint expected = _unlockTime2 > block.timestamp ? _unlockTime2 : block.timestamp;
        assertTrue(storedUnlock == expected);
    }
}

