pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTimeArg) public {
        // 1. Restrict to admissible domain: non-zero amount, unlockTimeArg can be past/future
        vm.assume(amount > 0);
        // 2. Fund c with enough Ether to collect
        address alice = makeAddr("alice");
        vm.deal(alice, amount);
        vm.prank(alice);
        uint snapshotTimestamp = block.timestamp;
        // We need c to have enough balance to pay out on Collect; pre-fund c
        // Put via alice
        vm.warp(snapshotTimestamp);
        c.Put{value: amount}(unlockTimeArg);
        // 3. The property: if we then Collect the whole balance after a time warp past the recorded unlockTime,
        //    the reference's clamping protects funds; the bug may allow draining earlier.
        //    We observe whether Collect succeeds (does not revert).
        vm.warp(c.Acc(alice).unlockTime + 1);
        bool ok = true;
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference always clamps unlockTime to at least block.timestamp, so after Put,
        // unlockTime >= snapshotTimestamp. Our warp is to unlockTime+1 which is > snapshotTimestamp.
        // Therefore Collect should always succeed in the reference; the bug may set a past unlockTime
        // that makes Collect fail earlier (or revert for other reasons) — wait, property must be universal.
        // Let's assert the boolean reflects behavior difference.
        // Actually, the reference should always succeed; we assert that it does.
        assertTrue(ok);
    }
}

