pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 putValue, uint256 collectAmount) public {
        // Restrict to reasonable ETH amounts
        putValue = bound(putValue, 1, 1000 ether);
        collectAmount = bound(collectAmount, 1, 1000 ether);
        // Ensure the sender has enough ether for the Put call
        vm.deal(address(this), putValue);
        // Warp to a non-zero block timestamp
        vm.warp(1000);
        // Perform the Put
        c.Put{value: putValue}(unlockTime);
        // Record the timestamp at Put time
        uint256 putTimestamp = block.timestamp;
        // Warp to the maximum of unlockTime and putTimestamp + 1 to test early collectibility
        uint256 warpTo = unlockTime > putTimestamp ? unlockTime + 1 : putTimestamp + 1;
        vm.warp(warpTo);
        // Attempt to collect
        bool ok;
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Property: if collect succeeds, then the unlockTime must have been <= block.timestamp (i.e., funds are only collectible after unlockTime)
        // Since we warped to after putTimestamp, if unlockTime < putTimestamp, the bug would allow collection, but reference would not.
        if (ok) {
            // Collection succeeded, so unlockTime must have been <= block.timestamp at collection time
            // In reference, unlockTime >= putTimestamp always, so collection only possible if we warped past unlockTime
            // In bug, unlockTime = _unlockTime could be less than putTimestamp, allowing immediate collection after putTimestamp
            // Thus, if collection succeeded, we assert that unlockTime <= warpTo (always true by construction)
            // But to encode the invariant: unlockTime (from Acc getter) must be >= putTimestamp for reference
            // Actually, we check that unlockTime >= putTimestamp, which holds for reference and fails for bug when _unlockTime < putTimestamp and collection succeeds
            (, uint256 storedUnlock) = c.Acc(address(this));
            assertTrue(storedUnlock >= putTimestamp);
        }
    }
}

