pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _value, uint256 _unlockTime, uint256 _collectAmt, uint256 _warpBlocks) public {
        // 1. domain: _value >= MinSum to allow Collect, _collectAmt <= _value, _unlockTime can be any
        vm.assume(_value >= c.MinSum());
        vm.assume(_collectAmt <= _value);
        vm.assume(_unlockTime >= block.timestamp); // any future or now, but not past for meaningful test
        vm.assume(_warpBlocks > 0);

        address actor = address(0x10);
        vm.deal(actor, _value);
        vm.prank(actor);
        c.Put{value: _value}(_unlockTime);

        // warp past the maximum of the original unlock time and block.timestamp at Put time + some blocks
        uint256 putBlockTimestamp = block.timestamp; // after Put executes
        uint256 targetUnlock = putBlockTimestamp > _unlockTime ? putBlockTimestamp : _unlockTime;
        vm.warp(targetUnlock + _warpBlocks);

        bool ok;
        vm.prank(actor);
        try c.Collect(_collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok); // reference: after warp past clamped unlockTime, Collect must succeed; bug: if _unlockTime is past, Collect might have succeeded too early (before intended unlock), but this assertion tests the reference's legitimate success path. Actually, the bug can also succeed here, but the reference MUST succeed here. The bug fails the property: after a Put with a future _unlockTime, warping past it must allow Collect; bug's unconditional assignment to a past _unlockTime would make Collect succeed even without warp, but that's not tested here. The property is: if we Put with future _unlockTime and warp past it, Collect must succeed. Bug also satisfies this. So we need a different property: after Put with _unlockTime in the future, the account's unlockTime must be >= that future time. The bug allows it to be less. So the assertion is: after Put, account's unlockTime >= max(block.timestamp at Put, _unlockTime). For reference it's clamped, for bug it's _unlockTime which could be less.
    }
}

