contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, uint256 warpTime) public {
        // 1. Keep inputs in admissible domain
        vm.assume(depositAmt > 0 && depositAmt < 1 ether); // smaller than MinSum to ensure no valid Collect
        vm.assume(collectAmt > 0 && collectAmt <= depositAmt);
        vm.assume(warpTime < type(uint256).max);

        // 2. Deploy adversarial callee that always reverts on value transfer
        Reverter reverter = new Reverter();
        // Use reverter's address as the owner of the deposit
        address actor = address(reverter);
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Put{value: depositAmt}(warpTime);

        // Remember state before Collect
        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(actor);
        uint cBalBefore = address(c).balance;

        // 3. Attempt Collect from the reverter, which will fail the inner call
        bool ok = true;
        vm.prank(actor);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: if the Collect call succeeded on the contract level (no revert in C itself),
        // the holder's balance MUST remain unchanged because the external send reverted.
        // The bug reduces balance unconditionally, so balance will differ.
        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(actor);
        assertTrue(!ok || (balanceAfter == balanceBefore));
    }
}

