        // Warp past unlockTime so the revert is not due to lock, but because the recipient (reverter) rejects ether
        vm.warp(unlockTime + 1);

        // Reverter will reject any incoming ether, making the low-level call in Collect fail
        uint256 balanceBefore = address(reverter).balance;
        uint256 accBalanceBefore = c.Acc(address(reverter)).balance;
        uint256 logLengthBefore = c.LogFile().History.length;

        bool ok;
        vm.prank(address(reverter));
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        bool invariantHolds = ok || (c.Acc(address(reverter)).balance == accBalanceBefore && c.LogFile().History.length == logLengthBefore);
        assertTrue(invariantHolds);
    }
}

